changeSet.sql:
CREATE TABLE saved_posts (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    profile_id BIGINT NOT NULL,
    post_id    BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    deleted_at TIMESTAMPTZ,

    CONSTRAINT SAVED_POSTS_PROFILE_FK FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
    CONSTRAINT SAVED_POSTS_POST_FK    FOREIGN KEY (post_id)    REFERENCES posts(id)    ON DELETE CASCADE
);

CREATE UNIQUE INDEX idx_saved_posts_unique_active ON saved_posts(profile_id, post_id) WHERE deleted_at IS NULL;
CREATE INDEX idx_saved_posts_profile              ON saved_posts(profile_id)          WHERE deleted_at IS NULL;
CREATE INDEX idx_saved_posts_post                 ON saved_posts(post_id)             WHERE deleted_at IS NULL;
